cd /user/linjiayin/harbor-runs/2e339a072ccf/workspace/observed_run && python3 - <<'EOF'
import json
rows=[]
for line in open('console-history.jsonl'):
    try: rows.append(json.loads(line))
    except: pass
print("n rows:", len(rows))
# find keys
keys=set()
for r in rows[:1]: keys.update(r.keys())
def get(r,*names):
    for n in names:
        if n in r: return r[n]
    return None
def series(*names):
    out=[]
    for r in rows:
        s=r.get('step') or r.get('global_step')
        v=get(r,*names)
        if v is not None: out.append((s,v))
    return out
for nm in ['critic/score/mean','response_length/mean','response_length/clip_ratio']:
    sv=series(nm)
    if sv:
        print(nm, "first:", sv[:3], "last:", sv[-3:])
        # print at key steps
        d=dict(sv)
        for st in [1,20,40,60,80,85,90,95,100,110,125,150]:
            if st in d: print("  step",st,"=",d[st])
EOF

