python3 - <<'EOF'
import json
rows=[json.loads(l) for l in open('console-history.jsonl')]
def show(names, steps=range(1,151)):
    print("step\t"+"\t".join(names.split()))
    for r in rows:
        s=r['console_step']
        if s in steps:
            vals=[]
            for n in names.split():
                v=r.get(n,'-')
                if isinstance(v,float): v=round(v,4)
                vals.append(str(v))
            print(s,"\t","\t".join(vals))
